fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    let row_count = x.len();
    let col_count = x[0].len();

    // Initialize the transposed matrix with col_count rows and row_count cols
    // Using with_capacity + push pattern for efficiency
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(col_count);

    for c in 0..col_count {
        let mut new_row = Vec::with_capacity(row_count);
        for r in 0..row_count {
            new_row.push(x[r][c]);
        }
        result.push(new_row);
    }

    result
}